package io.fireflysoftware.masters.core.services.insurance.reference;

import static io.fireflysoftware.masters.interfaces.dtos.insurance.reference.InsuranceReferenceContracts.*;
import java.lang.reflect.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class InsuranceReferenceLifecycleTest {
    static Revision first(){return InsuranceReferenceCodec.decode(InsuranceReferenceCodecTest.fixture("COVERAGE_WORDING").toString());}
    static Instant now(){return first().effectiveFrom().plusSeconds(1);}
    static Object invoke(String method,Class<?>[] types,Object...args){try{return Class.forName("io.fireflysoftware.masters.core.services.insurance.reference.InsuranceReferenceLifecycle").getMethod(method,types).invoke(null,args);}catch(InvocationTargetException e){if(e.getCause() instanceof RuntimeException error)throw error;throw new AssertionError(e.getCause());}catch(ReflectiveOperationException e){throw new AssertionError("Insurance reference lifecycle invariants missing",e);}}
    static Control publish(Control control,Revision prior,Revision next,long expected,Instant recordedAt){return (Control)invoke("publish",new Class<?>[]{Control.class,Revision.class,Revision.class,long.class,Instant.class},control,prior,next,expected,recordedAt);}
    static Control withdraw(Control control,long expected){return (Control)invoke("withdraw",new Class<?>[]{Control.class,long.class},control,expected);}
    static Revision next(Revision before){return new Revision(before.kind(),before.recordId(),UUID.fromString("aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee"),2,before.code(),before.effectiveFrom(),before.effectiveUntil(),before.definition(),before.provenance());}
    @Test void firstDataTransitionRequiresRevisionOneAndProducesSeparateCurrentControl(){var first=first();var control=publish(null,null,first,0,now());assertEquals(0,control.generation());assertEquals(State.ACTIVE,control.state());assertEquals(first.publicationId(),control.publicationId());assertEquals(1,control.revision());}
    @Test void subsequentPublicationAdvancesRevisionAndGenerationWithoutChangingPriorDefinition(){var first=first();String digest=InsuranceReferenceCodec.digest(first);var c=publish(null,null,first,0,now());var next=next(first);var updated=publish(c,first,next,0,now());assertEquals(1,updated.generation());assertEquals(2,updated.revision());assertEquals(digest,InsuranceReferenceCodec.digest(first));assertNotEquals(c.publicationId(),updated.publicationId());}
    @Test void publicationCannotSkipRevisionOrReusePublicationIdentity(){var f=first();var c=publish(null,null,f,0,now());var n=next(f);var gap=new Revision(n.kind(),n.recordId(),n.publicationId(),3,n.code(),n.effectiveFrom(),n.effectiveUntil(),n.definition(),n.provenance());assertThrows(IllegalArgumentException.class,()->publish(c,f,gap,0,now()));var reused=new Revision(n.kind(),n.recordId(),f.publicationId(),2,n.code(),n.effectiveFrom(),n.effectiveUntil(),n.definition(),n.provenance());assertThrows(IllegalArgumentException.class,()->publish(c,f,reused,0,now()));}
    @Test void exactExpectedControlGenerationIsRequired(){var f=first();var c=publish(null,null,f,0,now());assertThrows(IllegalArgumentException.class,()->publish(c,f,next(f),1,now()));}
    @Test void recordKindCodeAndCurrentPriorRevisionAreImmutableBindings(){var f=first();var c=publish(null,null,f,0,now());var changed=new Revision(Kind.EXCLUSION_WORDING,f.recordId(),UUID.randomUUID(),2,f.code(),f.effectiveFrom(),f.effectiveUntil(),f.definition(),f.provenance());assertThrows(IllegalArgumentException.class,()->publish(c,f,changed,0,now()));var renamed=new Revision(f.kind(),f.recordId(),UUID.randomUUID(),2,"DIFFERENT",f.effectiveFrom(),f.effectiveUntil(),f.definition(),f.provenance());assertThrows(IllegalArgumentException.class,()->publish(c,f,renamed,0,now()));assertThrows(IllegalArgumentException.class,()->publish(c,next(f),next(f),0,now()));}
    @Test void withdrawalOnlyChangesCurrentControlAndNeverDefinitionDigest(){var f=first();String digest=InsuranceReferenceCodec.digest(f);var c=publish(null,null,f,0,now());var withdrawn=withdraw(c,0);assertEquals(State.WITHDRAWN,withdrawn.state());assertEquals(1,withdrawn.generation());assertEquals(c.publicationId(),withdrawn.publicationId());assertEquals(c.revision(),withdrawn.revision());assertEquals(digest,InsuranceReferenceCodec.digest(f));}
    @Test void withdrawalReplayIsNotImplicitlyASecondMutationOrNewGrant(){var f=first();var c=withdraw(publish(null,null,f,0,now()),0);assertThrows(IllegalArgumentException.class,()->withdraw(c,0));assertThrows(IllegalArgumentException.class,()->withdraw(c,1));}
    @Test void rePublicationAfterWithdrawalRequiresANewRevisionAndPublication(){var f=first();var c=withdraw(publish(null,null,f,0,now()),0);var active=publish(c,f,next(f),1,now());assertEquals(2,active.revision());assertEquals(2,active.generation());assertEquals(State.ACTIVE,active.state());assertThrows(IllegalArgumentException.class,()->publish(c,f,f,1,now()));}
    @Test void futureAndExpiredDataCannotBePromotedToCurrent(){var f=first();assertThrows(IllegalArgumentException.class,()->publish(null,null,f,0,f.effectiveFrom().minusNanos(1000)));assertThrows(IllegalArgumentException.class,()->publish(null,null,f,0,f.effectiveUntil()));}
    @Test void openEndedDefinitionDoesNotAcceptAnUnsupportedRecordedClock(){var f=first();var open=new Revision(f.kind(),f.recordId(),f.publicationId(),1,f.code(),f.effectiveFrom(),null,f.definition(),f.provenance());assertThrows(IllegalArgumentException.class,()->publish(null,null,open,0,Instant.parse("+10000-01-01T00:00:00Z")));}
    @Test void generationsCannotWrap(){var f=first();var c=new Control(f.recordId(),f.kind(),f.publicationId(),1,Long.MAX_VALUE,State.ACTIVE);assertThrows(IllegalArgumentException.class,()->withdraw(c,Long.MAX_VALUE));}
    @Test void finiteObservationPreservesMicrosecondsButIsStillJustData(){var f=first();var c=publish(null,null,f,0,now());var at=now().plusNanos(1000);var observation=new Observation(f,c,at,at.plusSeconds(1));assertEquals(1000,observation.observedAt().getNano());assertEquals("InsuranceReferenceObservation",observation.toString());}
    @Test void withdrawnAndSupersededControlCannotProduceAnExactCurrentObservation(){var f=first();var c=publish(null,null,f,0,now());var withdrawn=withdraw(c,0);assertThrows(IllegalArgumentException.class,()->new Observation(f,withdrawn,now(),now().plusSeconds(1)));var advanced=publish(c,f,next(f),0,now());assertThrows(IllegalArgumentException.class,()->new Observation(f,advanced,now(),now().plusSeconds(1)));}
    @Test void observationCannotOutliveDefinitionOrThirtySeconds(){var f=first();var c=publish(null,null,f,0,now());assertThrows(IllegalArgumentException.class,()->new Observation(f,c,now(),now().plusSeconds(31)));assertThrows(IllegalArgumentException.class,()->new Observation(f,c,f.effectiveUntil().minusSeconds(1),f.effectiveUntil().plusNanos(1000)));}
    @Test void observationRefusesUnrepresentableNativePrecision(){var f=first();var c=publish(null,null,f,0,now());assertThrows(IllegalArgumentException.class,()->new Observation(f,c,now().plusNanos(1),now().plusSeconds(1)));}
}
